    .main-panel h1,.main-panel h2{letter-spacing:-.02em;line-height:1.4;color:var(--sb-text)}.main-panel .profile-toolbar{display:flex;flex-wrap:wrap!important;gap:6px!important;overflow:visible!important;padding:0 0 16px!important}.profile-toolbar a{font-size:12px!important;min-height:34px!important;padding:7px 11px!important;background:var(--sb-surface);border:1px solid var(--sb-line)!important;border-radius:11px!important;color:var(--sb-muted)!important}.profile-toolbar a.active{background:var(--sb-accent);color:var(--sb-surface)!important}
