    """#
    static var script: String {
        let literal = String(decoding: try! JSONSerialization.data(withJSONObject: [css]), as: UTF8.self)
        return #"""
        (()=>{
          if(location.hostname!=='linux.sb'||document.getElementById('sb-apple-client-design'))return;
          const css=document.createElement('style');css.id='sb-apple-client-design';css.textContent=LITERAL[0];document.head.append(css);
          const view=()=>location.hash==='#client-my'?'profile':location.hash==='#client-categories'?'categories':/^\/topic\/\d+/.test(location.pathname)?'topic':location.pathname==='/search'?'search':new URLSearchParams(location.search).get('tab')==='notifications'?'messages':location.pathname==='/login'?'login':(location.pathname==='/'||location.pathname==='/index.php'||location.pathname==='/topic_featured'||/^\/forum\/\d+/.test(location.pathname))?'home':'page';
          const applyView=()=>{document.documentElement.dataset.sbView=view();const title=document.querySelector('#sb-client-shell strong');if(title){const names={profile:'我的',categories:'分类',topic:'话题',search:'搜索',messages:'消息',login:'登录',home:'LINUX SB'};title.textContent=names[view()]||document.title.split(' - ')[0]||'社区'}};applyView();window.addEventListener('hashchange',applyView);
          const loadingStyle=document.createElement('style');loadingStyle.textContent=`#sb-route-loading{position:fixed;inset:0;z-index:205;background:var(--sb-bg);padding:20px 18px;overflow:auto;color:var(--sb-text)}#sb-route-loading header{display:flex;align-items:center;gap:16px;margin-bottom:28px}#sb-route-loading button{border:0;background:var(--sb-surface);color:var(--sb-muted);border-radius:50%;width:44px;height:44px;font:inherit;font-size:24px}#sb-route-loading h1{margin:0;font-size:21px}#sb-route-loading p{font-size:13px;color:var(--sb-muted)}.sb-loading-card{padding:22px;background:var(--sb-surface);border:1px solid var(--sb-line);border-radius:24px;margin-bottom:14px}.sb-loading-line{height:14px;border-radius:8px;background:var(--sb-soft);margin:14px 0;animation:sb-loading-pulse 1.1s ease-in-out infinite alternate}.sb-loading-line:first-child{width:68%;height:20px}.sb-loading-line:last-child{width:42%}@keyframes sb-loading-pulse{to{opacity:.4}}@media(prefers-reduced-motion:reduce){.sb-loading-line{animation:none}}`;document.head.append(loadingStyle);
          let loadingTimer;const clearLoading=()=>{clearTimeout(loadingTimer);document.getElementById('sb-route-loading')?.remove()};
          window.sbShowRouteLoading=(href,label)=>{const url=new URL(href,location.href);if(url.origin!==location.origin||url.href===location.href||(url.pathname===location.pathname&&url.search===location.search&&url.hash))return;clearLoading();const overlay=document.createElement('section');overlay.id='sb-route-loading';overlay.setAttribute('role','status');overlay.setAttribute('aria-live','polite');const header=document.createElement('header');const cancel=document.createElement('button');cancel.textContent='‹';cancel.setAttribute('aria-label','取消加载');cancel.onclick=()=>{window.stop();clearLoading()};const heading=document.createElement('h1');heading.textContent=label||(/^\/topic\/\d+/.test(url.pathname)?'话题':url.pathname==='/search'?'搜索':url.search.includes('tab=notifications')?'消息':'社区');header.append(cancel,heading);overlay.append(header);const status=document.createElement('p');status.textContent='正在加载内容…';overlay.append(status);for(let i=0;i<3;i++){const card=document.createElement('div');card.className='sb-loading-card';for(let j=0;j<3;j++){const line=document.createElement('div');line.className='sb-loading-line';card.append(line)}overlay.append(card)}document.body.append(overlay);loadingTimer=setTimeout(()=>{status.textContent='连接较慢，请稍候；也可以点左上角返回。'},12000)};
